using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns a strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> => Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2. TryGetTypeInfo<T>() — probe without throwing
//    With the web defaults resolver every type resolves, so this succeeds:
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> => resolved ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person> => not available");

// Now use options with a source-gen context that only knows about Person.
// Asking for Order will fail gracefully via TryGetTypeInfo<T>.
var sgOptions = new JsonSerializerOptions { TypeInfoResolver = DemoContext.Default };

if (sgOptions.TryGetTypeInfo<Order>(out JsonTypeInfo<Order>? orderInfo))
    Console.WriteLine($"TryGetTypeInfo<Order> => resolved ({orderInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Order> => not available (source-gen context lacks Order)");

// Types
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

